TEST(ESM4PhysicalCombat, OriginalFirstPunchHealthObservation)
{
    // Original 1.2.0416, M15-S2-ORACLE-HAND-01: ordinary first punch, no
    // equipment/spells on the victim, default difficulty. Console displays
    // victim health 500.00 -> 498.58. Exact contact fatigue was not captured.
    const ESM4::HandToHandSettings hand{0, 1, 0, .75f, 1, 15, 1, .5f};
    const auto full = ESM4::handToHandDamage({10, 50, 40, 1.f}, hand, installed);
    EXPECT_NEAR(500.f - full.mHealth, 498.58f, .0051f);
    // Independently derived lower damage bound if all seven attack fatigue
    // points were still missing at contact: 1 + 14*(.1*.3*.975) = 1.4095.
    const auto depleted = ESM4::handToHandDamage({10, 50, 40, .95f}, hand, installed);
    EXPECT_NEAR(depleted.mHealth, 1.4095f, .00001f);
    EXPECT_LE(depleted.mHealth, full.mHealth);
}

TEST(ESM4PhysicalCombat, OriginalFirstPowerPunchUsesPreDebitFatigue)
{
    // M15-S2-ORACLE-HAND-03: first held attack, 500.00 -> 496.45 health.
    // Original player contact handler runs before this attack's fatigue debit.
    const ESM4::HandToHandSettings hand{0, 1, 0, .75f, 1, 15, 1, .5f};
    const ESM4::CombatMasterySettings mastery{{25, 50, 75, 100}};
    const ESM4::PowerAttackSettings power{2.5f, 3.f, 2.5f, 2.5f, 2.5f};
    const auto damage = ESM4::handToHandDamage({10, 50, 40, 1.f}, hand, installed);
    const float multiplier = ESM4::powerAttackMultiplier(10, ESM4::PowerAttackDirection::Standing, power, mastery);
    EXPECT_NEAR(500.f - damage.mHealth * multiplier, 496.45f, .0051f);
    EXPECT_FLOAT_EQ(ESM4::attackFatigueCost(0, true, {7, .1f, 5}), 35);
    // A wrongly ordered debit produces a distinguishable health result.
    const auto wrongOrder = ESM4::handToHandDamage({10, 50, 40, .75f}, hand, installed);
    EXPECT_GT(500.f - wrongOrder.mHealth * multiplier, 496.57f);
}

TEST(ESM4PhysicalCombat, OriginalFirstSwordHealthObservation)
{
    // M15-S2-ORACLE-WEAPON-01: normal inventory pickup/equip, first ordinary
    // swing, naked victim, neutral difficulty. Original health 500 -> 483.38.
    // Independently predicted 100*.5*1*(.2+.1*1.5)*(.75+.4*.5) = 16.625.
    ESM4::WeaponDamageInput input{10, 50, 40, 100, 1.f, 1.f};
    EXPECT_NEAR(ESM4::weaponDamage(input, installed), 16.625f, .00001f);
    EXPECT_NEAR(500.f - ESM4::weaponDamage(input, installed), 483.38f, .0051f);
    input.mFatigueRatio = .95f; // Incorrectly debit seven fatigue before contact.
    EXPECT_GT(500.f - ESM4::weaponDamage(input, installed), 483.78f);
}

TEST(ESM4PhysicalCombat, WeaponWearUsesBaseDamage)
{
    const ESM4::DurabilitySettings settings{.06f, 9.f};
    for (const auto& c : {std::pair{0, 0.f}, {1, .06f}, {99, 5.94f}, {100, 6.f},
             {101, 6.06f}, {65535, 3932.1f}})
        EXPECT_NEAR(ESM4::weaponWear(c.first, settings), c.second, std::max(.000001f, c.second * 1e-7f));
    EXPECT_EQ(ESM4::weaponWear(65535, {0, 9}), 0);
}

TEST(ESM4PhysicalCombat, ArmorWearUsesAbsorbedDamageWithoutIntermediateRounding)
{
    const ESM4::DurabilitySettings settings{.06f, 9.f};
    for (const auto& c : {std::pair{0.f, 0.f}, {.01f, 9.f}, {.5f, 450.f}, {.85f, 765.f}, {1.f, 900.f}})
        EXPECT_NEAR(ESM4::armorWear(100, c.first, settings), c.second, .0001f);
    EXPECT_EQ(ESM4::armorWear(0, 1, settings), 0);
    EXPECT_EQ(ESM4::armorWear(1, 1, settings), 9);
    EXPECT_EQ(ESM4::armorWear(100, 1, {.06f, 0}), 0);
    const float below = std::nextafter(.5f, 0.f), above = std::nextafter(.5f, 1.f);
    EXPECT_LT(ESM4::armorWear(100, below, settings), 450);
    EXPECT_GT(ESM4::armorWear(100, above, settings), 450);
    // One original x87 store after both products: exact binary operands
    // (1+2^-23)*(1-2^-24)*3 round to 3+2^-22, not 3.
    EXPECT_EQ(ESM4::armorWear(std::nextafter(1.f, 2.f), std::nextafter(1.f, 0.f), {0, 3}),
        std::nextafter(3.f, 4.f));
}

TEST(ESM4PhysicalCombat, DurabilityRejectsInvalidInputsAndOverflow)
{
    const ESM4::DurabilitySettings settings{.06f, 9.f};
    for (float invalid : {-1.f, std::numeric_limits<float>::infinity(), std::numeric_limits<float>::quiet_NaN()})
    {
        EXPECT_THROW(ESM4::weaponWear(1, {invalid, 9}), std::invalid_argument);
        EXPECT_THROW(ESM4::armorWear(1, 1, {.06f, invalid}), std::invalid_argument);
        EXPECT_THROW(ESM4::armorWear(invalid, 1, settings), std::invalid_argument);
        if (invalid != -1.f)
            EXPECT_THROW(ESM4::armorWear(1, invalid, settings), std::invalid_argument);
    }
    EXPECT_THROW(ESM4::armorWear(1, std::nextafter(1.f, 2.f), settings), std::invalid_argument);
    EXPECT_THROW(ESM4::weaponWear(65535, {std::numeric_limits<float>::max(), 9}), std::invalid_argument);
    EXPECT_THROW(ESM4::armorWear(std::numeric_limits<float>::max(), 1, settings), std::invalid_argument);
}

